(()=>{
 const A=window.AyanAccount,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const request=async(url,data)=>{const r=await fetch(url,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const value=await r.json();if(!r.ok)throw Error(value.error||'Не удалось выполнить запрос');return value;};
 const lessonURL='/api/lesson?role='+A.role+(A.role==='teacher'?'&child='+A.child:'');
 let lesson=null,index=0,large=false,paused=false;
 function panel(html){const el=document.createElement('section');el.className='account-panel';el.innerHTML=html;return el;}
 async function ask(prompt,context){return (await request('/api/assistant',{prompt,context})).text;}
 function teacherPanel(){
  if(document.querySelector('#product-teacher'))return;
  const el=panel('<h2>Ученики и занятие</h2><div class="row"><label for="student-select">Ученик</label><select id="student-select">'+A.children.map(c=>'<option value="'+c.id+'" '+(c.id===A.child?'selected':'')+'>'+esc(c.label)+'</option>').join('')+'</select><button class="secondary" id="new-student">Добавить ученика</button><button class="secondary" id="child-invite">Вход ребёнка</button><button class="secondary" id="parent-invite">Отчёт родителю</button></div><p class="invite-result" id="invite-result" role="status"></p><hr><h2>Объяснение темы по шагам</h2><p>Материал появится у выбранного ученика после вашей проверки и публикации</p><form id="lesson-editor"><label for="lesson-title">Тема урока</label><input id="lesson-title" name="title" placeholder="Например, сложение в пределах 10" required maxlength="160"><label for="lesson-steps">Объяснение · один шаг на строке</label><textarea id="lesson-steps" name="steps" rows="5" required placeholder="Посмотри на два кружка.\nДобавь ещё три кружка.\nПосчитай все кружки вместе."></textarea><label for="lesson-question">Вопрос для самостоятельной проверки</label><input id="lesson-question" name="question" placeholder="Сколько будет 2 + 3?" required><label for="lesson-answer">Короткий правильный ответ</label><input id="lesson-answer" name="answer" placeholder="5" required><div class="actions"><button class="secondary" type="button" id="ai-draft">Помочь с объяснением · ИИ</button><button class="primary">Проверено — назначить урок →</button></div><p class="status-line" id="lesson-status" role="status"></p></form>');el.id='product-teacher';document.querySelector('#app').prepend(el);
  document.querySelector('#student-select').onchange=e=>{sessionStorage.setItem('ayan.selected.'+A.me.id,e.target.value);location.reload();};
  document.querySelector('#new-student').onclick=async()=>{const label=prompt('Имя или псевдоним ученика. Фамилия не нужна.');if(!label)return;try{const c=await request('/api/children',{label});sessionStorage.setItem('ayan.selected.'+A.me.id,c.id);location.reload();}catch(e){document.querySelector('#invite-result').textContent=e.message;}};
  for(const [id,url]of [['child-invite','/api/invite'],['parent-invite','/api/parent/invite']])document.querySelector('#'+id).onclick=async()=>{try{await A.flush();const r=await request(url,{child:A.child});const out=document.querySelector('#invite-result');out.replaceChildren();const a=document.createElement('a');a.href=r.url;a.textContent=r.url;a.target='_blank';a.rel='noopener';out.append(id==='child-invite'?'Одноразовая ссылка для ребёнка · действует 24 часа: ':'Ссылка на отчёт · действует 30 дней. Новая ссылка отменяет прежнюю: ',a);}catch(e){document.querySelector('#invite-result').textContent=e.message;}};
  request(lessonURL).then(l=>{if(!l)return;const f=document.querySelector('#lesson-editor');if(!f)return;f.elements.title.value=l.title;f.elements.steps.value=l.steps.join('\n');f.elements.question.value=l.question;f.elements.answer.value=l.answer;}).catch(()=>{});
  document.querySelector('#lesson-editor').onsubmit=async e=>{e.preventDefault();const f=e.target,s=document.querySelector('#lesson-status');s.textContent='Сохраняем…';try{const data=Object.fromEntries(new FormData(f));data.steps=data.steps.split('\n').filter(x=>x.trim());await request(lessonURL,data);s.textContent='Урок назначен. Ребёнок увидит его после обновления своей страницы.';}catch(e){s.textContent=e.message;}};
  document.querySelector('#ai-draft').onclick=async e=>{const f=document.querySelector('#lesson-editor'),s=document.querySelector('#lesson-status');if(!f.elements.title.value.trim()){s.textContent='Сначала укажите тему урока';return;}e.target.disabled=true;s.textContent='Аян составляет объяснение…';try{f.elements.steps.value=await ask('Разбей тему на 3–5 простых шагов. Один шаг на строке. Без нумерации, заголовков и разметки. Тема: '+f.elements.title.value,f.elements.steps.value);s.textContent='Черновик ИИ. Проверьте каждый шаг перед публикацией.';}catch(e){s.textContent=e.message;}finally{e.target.disabled=false;}};
 }
 function mountChild(){
  const mark=document.querySelector('.world-brand .brand-leaf');if(mark&&!mark.querySelector('img'))mark.innerHTML='<img src="/assets/ayan-mark.svg" width="36" height="36" alt="">';
  const main=document.querySelector('.world-main');if(!main||document.querySelector('#assigned-lesson'))return;
  const el=panel('<span class="eyebrow">Моё занятие</span><h2>'+esc(lesson?.title||'Учитель готовит занятие')+'</h2><p>'+ (lesson?'Посмотрим на объяснение и попробуем вместе':'Когда учитель назначит тему, она появится здесь')+'</p>'+(lesson?'<button class="primary" id="open-lesson">Начать занятие →</button>':''));el.id='assigned-lesson';main.prepend(el);document.querySelector('#open-lesson')?.addEventListener('click',openLesson);
 }
 let eventQueue=Promise.resolve();
 const event=(kind,value='')=>{eventQueue=eventQueue.catch(()=>{}).then(()=>request('/api/lesson/event',{kind,value}));return eventQueue.catch(()=>{});};
 function openLesson(){document.querySelector('#lesson-dialog')?.remove();const d=document.createElement('dialog');d.id='lesson-dialog';d.style.cssText='width:min(960px,calc(100% - 24px));max-height:94dvh;border:1px solid #dce5d3;border-radius:20px;padding:0';document.body.append(d);d.showModal();draw();event('step',String(index+1));}
 function draw(){const d=document.querySelector('#lesson-dialog');if(!d)return;d.innerHTML='<div class="lesson-reader" style="font-size:'+(large?'22':'17')+'px"><div class="actions"><button class="secondary" id="lesson-close">← К моим заданиям</button><button class="secondary" id="lesson-pause">'+(paused?'Продолжить':'Перерыв')+'</button><button class="secondary" id="lesson-size" aria-pressed="'+large+'">Крупный текст</button></div><p style="margin-top:24px">Шаг '+(index+1)+' из '+(lesson.steps.length+1)+'</p><h1>'+esc(lesson.title)+'</h1>'+(paused?'<div class="lesson-step">Можно отдохнуть. Занятие подождёт.</div>':index<lesson.steps.length?'<div class="lesson-step" style="font-size:'+(large?'30':'22')+'px">'+esc(lesson.steps[index])+'</div><div class="actions"><button class="secondary" id="speak-step">Послушать</button><button class="secondary" id="repeat-step">Показать предыдущий шаг</button><button class="primary" id="next-step">Дальше →</button></div>':'<div class="lesson-step">'+esc(lesson.question)+'</div><form id="answer-form"><label for="lesson-response">Твой ответ</label><input id="lesson-response" required maxlength="200" style="padding:16px;width:100%;font:inherit"><button class="primary" style="margin-top:16px">Проверить</button></form>')+'<p id="lesson-feedback" role="status" style="margin:24px 0"></p><div class="account-panel"><h2>Попросить Аяна объяснить</h2><p>ИИ может ошибаться. Если объяснение непонятно, позови взрослого.</p><button class="secondary" id="teacher-hint">Повторить объяснение учителя</button><form id="assistant-form"><label for="assistant-question">Что объяснить?</label><textarea id="assistant-question" required maxlength="2000" placeholder="Объясни этот шаг на простом примере"></textarea><button class="secondary">Спросить Аяна · ИИ</button></form><p id="assistant-reply" role="status" style="white-space:pre-wrap"></p></div></div>';
 d.querySelector('#lesson-close').onclick=()=>{speechSynthesis?.cancel();d.close();d.remove();};d.querySelector('#lesson-pause').onclick=()=>{paused=!paused;if(paused){speechSynthesis?.cancel();event('pause');}draw();};d.querySelector('#lesson-size').onclick=()=>{large=!large;draw();};
 d.querySelector('#next-step')?.addEventListener('click',()=>{index++;event('step',String(index+1));draw();});
 d.querySelector('#repeat-step')?.addEventListener('click',()=>{index=Math.max(0,index-1);event('hint');draw();});
 d.querySelector('#speak-step')?.addEventListener('click',()=>{if(!window.speechSynthesis)return;const u=new SpeechSynthesisUtterance(lesson.steps[index]);u.lang='ru-RU';u.rate=.85;speechSynthesis.cancel();speechSynthesis.speak(u);});
 d.querySelector('#teacher-hint').onclick=()=>{event('hint');d.querySelector('#assistant-reply').textContent=lesson.steps[Math.min(index,lesson.steps.length-1)];};
 d.querySelector('#answer-form')?.addEventListener('submit',async e=>{e.preventDefault();const result=await event('answer',d.querySelector('#lesson-response').value);d.querySelector('#lesson-feedback').textContent=result?.value==='correct'?'Верно. Ты завершил задание. Результат сохранён.':'Попробуем ещё раз. Можно вернуться к объяснению и попросить помощь.';});
 d.querySelector('#assistant-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button'),out=d.querySelector('#assistant-reply');b.disabled=true;out.textContent='Аян думает…';event('hint');try{out.textContent=await ask(d.querySelector('#assistant-question').value);}catch(e){out.textContent=e.message;}finally{b.disabled=false;}};
 }
 function decorate(){document.querySelectorAll('.brand #logo,.mobile-brand').forEach(el=>{el.innerHTML='<img src="/assets/ayan-mark.svg" alt="" width="40" height="40">';});document.querySelectorAll('.mode-switch').forEach(el=>el.remove());if(A.role==='teacher')teacherPanel();else mountChild();}
 request(lessonURL).then(l=>{lesson=l;document.querySelector('#assigned-lesson')?.remove();decorate();}).catch(()=>decorate());
 new MutationObserver(()=>{if(A.role==='child')mountChild();}).observe(document.querySelector('#world'),{childList:true});
 window.addEventListener('ayan:render',decorate);decorate();
})();
